function surface(input) {
    const u = (input.u - 0.5) * 2 * Math.PI;
    const v = (input.v - 0.5) * 2 * Math.PI;
    const delta = input.delta || 0.55;
    const kappa = input.kappa || -0.08;
    const hz = input.hz || 0.4;
    const fitness = input.fitness || 0.9;
    const t = input.t || 0;

    // Constellation geometry: sonic group as parametric surface
    // delta (tempo) drives orbital speed
    // kappa (LRA curvature) warps the surface
    // hz (spectral centroid) sets spectral color
    // fitness (coherence) controls surface smoothness

    const r_base = 3 + fitness * 2;
    const warp = kappa * 8;
    const orbit = delta * 2;

    // Toroidal constellation with beat-driven warping
    const R = r_base + Math.sin(u * 3 + t * orbit) * warp;
    const x = (R + Math.cos(v)) * Math.cos(u);
    const y = (R + Math.cos(v)) * Math.sin(u);
    const z = Math.sin(v) + Math.sin(u * 5 + t * orbit * 2) * Math.abs(kappa) * 3;

    // Color from spectral signature
    const hue = hz * 6.2832;
    const r_col = 0.5 + 0.5 * Math.sin(hue + u);
    const g_col = 0.5 + 0.5 * Math.sin(hue + u + 2.094);
    const b_col = 0.5 + 0.5 * Math.sin(hue + u + 4.189);
    const a = 0.7 + fitness * 0.3;

    return { x, y, z, r: r_col, g: g_col, b: b_col, a };
}
